// Starship Window: destinations and prompts.
//
// Prompts describe ONLY the view straight ahead. Never mention a cockpit,
// window or ship, or Orbis may paint its own over ours.

export type Destination = {
  id: string;
  name: string;
  era: string;
  /** Log line written on arrival. */
  log: string;
  /**
   * Hand-written: a fragment finishing "Drifting slowly forward through …".
   * Generated by the director: complete sentences describing the view ahead.
   */
  view: string;
  /** Written by the director (complete-sentence view). */
  generated?: boolean;
  /** Six-word hook shown on the console key. */
  teaser?: string;
};

/** The Orbis prompt for being at this destination. */
export function promptFor(destination: Destination) {
  return destination.generated
    ? scenePrompt(destination.view)
    : viewPrompt(destination.view);
}

/** For complete-sentence views (director worlds and events). */
export function scenePrompt(view: string) {
  return `${view.trim().replace(/\s+$/, "")} Seen straight ahead while drifting slowly forward with steady motion. Cinematic and photorealistic, one continuous shot with no cuts.`;
}

export function viewPrompt(view: string) {
  return `Drifting slowly forward through ${view}, seen straight ahead, with steady forward motion. Cinematic and photorealistic, one continuous shot with no cuts.`;
}

/** Step one of every jump; the destination follows a few seconds later. */
export const JUMP_PROMPT =
  "Accelerating forward through space, stars stretching into long streaks of white and blue light rushing toward the edges, a bright glow at the centre. One continuous shot with no cuts.";

